  void RefreshHome()
  {
   if(game==null||home==null)return;game.CashText.text="$"+game.Profile.Cash.ToString("N0");game.LevelText.text="Lv "+game.Profile.Level+"\n"+game.Profile.Xp+" / "+RepairRules.XpTarget(game.Profile)+" XP";if(game.ToolText!=null)game.ToolText.text=T("WERKZEUG\n","TOOL\n")+game.ToolName();
   var job=game.ActiveJob;game.JobTitle.text=job==null?T("Neuer Auftrag","New service call"):T(job.TitleDe,job.Title);game.JobMeta.text=job==null?T("Im Tablet auswählen","Choose in the tablet"):job.Address+"\n$"+job.Reward+" · "+job.Xp+" XP";
   if(missionPreview!=null){missionPreview.transform.parent.gameObject.SetActive(job!=null);if(job!=null&&missionPreviewKey!=job.Id&&Application.isPlaying){missionPreview.texture=Studio().Thumbnail(job.Id);missionPreviewKey=job.Id;}}
   bool guide=game.Tutorial.Active;missionEyebrow.text=guide?(compactDriving?"TUTORIAL "+(game.Tutorial.Step+1)+"/7":T("ERSTER AUFTRAG · ","FIRST CALL · ")+(game.Tutorial.Step+1)+" / 7"):T("SERVICE-AUFTRAG","SERVICE CALL");tutorialCard.gameObject.SetActive(guide);if(guide)tutorialInstruction.text=compactDriving?TutorialHintCompact():TutorialHint();
   distance.gameObject.SetActive(job!=null);distance.text=job!=null?Mathf.RoundToInt(game.Distance)+" m":"";tutorialSkip.gameObject.SetActive(guide);if(minimap!=null)minimap.gameObject.SetActive(!guide&&job!=null);
   bool can=job!=null&&game.Vehicle!=null&&RepairRules.IsArrival(game.Vehicle.transform.position.x-job.DestinationX,game.Vehicle.transform.position.z-job.DestinationZ,game.Vehicle.SpeedKmh/3.6f);arrival.GetComponentInChildren<Text>().text=compactDriving?(job==null?(guide&&game.Tutorial.Step==6?T("Gerät","Tool"):T("Auftrag","Calls")):can?T("Start","Start"):T("Los","Go")):(job==null?(guide&&game.Tutorial.Step==6?T("Werkzeug","Tools"):T("Aufträge","Dispatch")):can?T("Reparieren","Repair"):T("Navigieren","Navigate"));
   if(speed!=null)speed.text=(game.Vehicle!=null?Mathf.RoundToInt(game.Vehicle.SpeedKmh):0)+" KM/H";
   if(minimap!=null&&game.Vehicle!=null){float map=minimap.rect.width;var van=minimap.Find("MapVan")as RectTransform;var destination=minimap.Find("MapDestination")as RectTransform;if(van!=null)van.anchoredPosition=new Vector2(Mathf.Clamp(.5f+game.Vehicle.transform.position.x/90,.05f,.9f)*map,-Mathf.Lerp(map-16,8,Mathf.Clamp01(game.Vehicle.transform.position.z/440)));if(destination!=null){destination.gameObject.SetActive(job!=null);if(job!=null)destination.anchoredPosition=new Vector2((.5f+job.DestinationX/90)*map,-Mathf.Lerp(map-16,8,job.DestinationZ/440));}}
  }
  public void RefreshProfile(){if(game==null||rendering)return;UiFactory.HighContrast=game.Profile.HighContrast;RefreshHome();if(game.ResultOpen){page=9;modal.gameObject.SetActive(true);RenderPage();}else if(game.RepairOpen){page=8;modal.gameObject.SetActive(true);RenderPage();}else if(game.TabletOpen){modal.gameObject.SetActive(true);RenderPage();}else if(modal!=null)modal.gameObject.SetActive(false);home.gameObject.SetActive(!ModalOpen);}
  public void ShowPage(int value){if(game.NativePresenting?.Invoke()==true||game.RepairOpen)return;if(game.ResultOpen)game.DismissResult();int next=value==9?9:Mathf.Clamp(value,0,7);if(ModalOpen&&page!=next)menuParents.Push(page);else if(!ModalOpen)menuParents.Clear();page=next;modal.gameObject.SetActive(true);game.SetTabletOpen(true);RenderPage();if(page==7)game.Videos?.Prepare();}
  public void Back(){if(game.NativePresenting?.Invoke()==true||game.RepairOpen)return;if(menuParents.Count==0){ShowPage(9);return;}page=menuParents.Pop();modal.gameObject.SetActive(true);game.SetTabletOpen(true);RenderPage();}
  public void Close(){if(game.NativePresenting?.Invoke()==true)return;menuParents.Clear();modal.gameObject.SetActive(false);home.gameObject.SetActive(true);repairHold?.ResetInput();if(game.ResultOpen)game.DismissResult();else if(game.RepairOpen)game.CloseRepair();else game.SetTabletOpen(false);}
  public void ShowNotice(string text){if(notice==null)return;notice.text=text;noticeUntil=Time.unscaledTime+3;notice.gameObject.SetActive(true);}
  void Clear(RectTransform root){for(int i=root.childCount-1;i>=0;i--){var child=root.GetChild(i).gameObject;child.SetActive(false);DestroyObject(child);}}
